2d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441: *\u00ab\u043c\u043e\u0436\u0435\u0442 \u043b\u0438 \u043c\u043e\u0434\u0435\u043b\u044c \u0434\u0430\u043d\u043d\u043e\u0433\u043e \u043a\u043b\u0430\u0441\u0441\u0430 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0435 \u0431\u044b\u0441\u0442\u0440\u044b\u0435 \u043e\u0441\u0446\u0438\u043b\u043b\u044f\u0446\u0438\u0438\u00bb*, \u0430 \u043d\u0435 \u00ab\u0434\u0435\u043b\u0430\u0435\u0442 \u043b\u0438 \u0438\u043c\u0435\u043d\u043d\u043e \u044d\u0442\u043e\u0442 MDGEN \u0438\u043c\u0435\u043d\u043d\u043e \u0442\u0430\u043a\u00bb. \u042d\u0442\u043e \u043d\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u0434\u0438\u0437\u0430\u0439\u043d\u0430, \u0430 \u0435\u0433\u043e \u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435 \u0438\u0437 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u044f \u043a\u043e\u0434\u0430; \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a assumption \u0441 \u044d\u043a\u0441\u043f\u043b\u0438\u0446\u0438\u0442\u043d\u044b\u043c caveat. \u041d\u0438\u043a\u0430\u043a\u0438\u0435 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u044b \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u0438\u0441\u044c \u2014 \u044d\u0442\u043e design-only \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442.\n\n## 1. Rationale\n\nSubsampling \u0441 \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u043c N (\u0431\u0435\u0440\u0451\u043c \u043a\u0430\u0436\u0434\u044b\u0439 N-\u0439 \u0448\u0430\u0433) \u0434\u0435\u043b\u0430\u0435\u0442 \u0441\u0435\u0442\u043a\u0443 \u0441 Nyquist-\u0447\u0430\u0441\u0442\u043e\u0442\u043e\u0439 f_Nyq(N) = 1/(2N) (\u0446\u0438\u043a\u043b\u043e\u0432 \u043d\u0430 full-resolution \u0448\u0430\u0433). \u041e\u0442\u0441\u044e\u0434\u0430 \u0434\u0432\u0430 \u043f\u0440\u0438\u043d\u0446\u0438\u043f\u0438\u0430\u043b\u044c\u043d\u043e \u0440\u0430\u0437\u043d\u044b\u0445 \u0440\u0435\u0436\u0438\u043c\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 **\u043d\u0435\u043b\u044c\u0437\u044f \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0442\u044c \u0432 \u043e\u0434\u043d\u043e\u043c \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0435**, \u0438\u043d\u0430\u0447\u0435 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u00ab\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u043b\u0438\u00bb \u043d\u0435\u043e\u0434\u043d\u043e\u0437\u043d\u0430\u0447\u0435\u043d:\n\n- **Arm A \u2014 band-limited (f < f_Nyq(N)):** \u0441\u0438\u0433\u043d\u0430\u043b \u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u043c \u2014 subsampling \u043e\u0431\u0440\u0430\u0442\u0438\u043c (sinc-\u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0446\u0438\u044f \u2014 \u043e\u043f\u0442\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0442\u043e\u0440). \u041f\u0440\u043e\u0433\u043d\u043e\u0437: \u0445\u043e\u0440\u043e\u0448\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u0434\u043e\u043b\u0436\u043d\u0430 **\u043f\u0440\u0435\u0432\u043e\u0441\u0445\u043e\u0434\u0438\u0442\u044c** \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0442\u043e\u0440\u044b \u0438 \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0430\u0442\u044c sinc.\n- **Arm B \u2014 aliased (f > f_Nyq(N)):** \u0432\u044b\u0441\u043e\u043a\u043e\u0447\u0430\u0441\u0442\u043e\u0442\u043d\u0430\u044f \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f **\u0431\u0435\u0437\u0432\u043e\u0437\u0432\u0440\u0430\u0442\u043d\u043e \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u0430** \u0432 subsampled \u0434\u0430\u043d\u043d\u044b\u0445 (\u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u043f\u0440\u0435\u0434\u0435\u043b \u2014 \u043d\u0438\u043a\u0430\u043a\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u0435\u0451 \u043d\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442). \u0412 input \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043b\u0438\u0448\u044c \u0430\u043b\u0438\u0430\u0441-\u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u043d\u0430 f_alias = min_k |f \u2212 k/N| < f_Nyq(N). \u041f\u0440\u043e\u0433\u043d\u043e\u0437: **\u043d\u0438 \u043e\u0434\u043d\u0430 \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u0430 \u00ab\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0442\u044c\u00bb \u0438\u0441\u0442\u0438\u043d\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u043e\u0442\u0443** \u2014 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0430\u0432\u0434\u043e\u043f\u043e\u0434\u043e\u0431\u0438\u0435 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438; \u043c\u043e\u0434\u0435\u043b\u044c \u043c\u043e\u0436\u0435\u0442 \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u043e \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0441\u0442\u0438 \u0430\u043b\u0438\u0430\u0441-\u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435, \u0438 \u044d\u0442\u043e \u0434\u043e\u043b\u0436\u043d\u043e \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e.\n\n\u0420\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0434\u0432\u0430 \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u044b\u0445 arms \u0441 \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u043c\u0438 \u0438\u0441\u0445\u043e\u0434\u0430\u043c\u0438 \u0434\u0435\u043b\u0430\u0435\u0442 \u043e\u0442\u0432\u0435\u0442 \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u043c \u0438 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u043c\u044b\u043c: Arm A \u2192 \u00ab\u043c\u043e\u0436\u0435\u0442 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c (band-limited \u0447\u0430\u0441\u0442\u044c)\u00bb, Arm B \u2192 \u00ab\u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c (\u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c), \u0442\u043e\u043b\u044c\u043a\u043e \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u0440\u0430\u0432\u0434\u043e\u043f\u043e\u0434\u043e\u0431\u043d\u043e\u0435\u00bb.\n\n## 2. Spec \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 (\u0442\u043e\u0447\u043d\u043e, stdlib: math, random, json)\n\n**\u0421\u0438\u0441\u0442\u0435\u043c\u0430:** M = 4 torsion angles \u03c6_i(t), i = 1..4, unwrapped radians. **\u0414\u043b\u0438\u043d\u0430:** T = 4096 full-resolution \u0448\u0430\u0433\u043e\u0432 (t = 0..4095). **Seeds:** S = 20 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0445 (random.seed(1000+s)).\n\n**\u0424\u043e\u0440\u043c\u0443\u043b\u0430 (\u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0443\u0433\u043b\u0430 i):**\n\u03c6_i(t) = S_i(t) + A \u00b7 sin(2\u03c0 f_i t + \u03c60_i) + \u03b5_i(t)\n\n- **\u041c\u0435\u0434\u043b\u0435\u043d\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430** S_i(t): random walk, S_i(0)=0, S_i(t) = S_i(t\u22121) + N(0, \u03c3_s), \u03c3_s = 0.02 \u0440\u0430\u0434/\u0448\u0430\u0433 (std \u043d\u0430 T \u2248 1.3 \u0440\u0430\u0434 \u2014 \u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u044b\u0439 \u0440\u0430\u0437\u043c\u0430\u0445; \u0431\u0435\u0437 clamp, \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u043a\u0430\u043a \u0443\u043f\u0440\u043e\u0449\u0435\u043d\u0438\u0435).\n- **\u0411\u044b\u0441\u0442\u0440\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430:** A = 0.3 \u0440\u0430\u0434 (~17\u00b0), \u03c60_i ~ U[0, 2\u03c0) (\u0444\u0438\u043a\u0441. seed), \u0447\u0438\u0441\u0442\u0430\u044f \u0441\u0438\u043d\u0443\u0441\u043e\u0438\u0434\u0430 (\u0431\u0435\u0437 \u0437\u0430\u0442\u0443\u0445\u0430\u043d\u0438\u044f \u2014 \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u0438 \u0442\u043e\u0447\u043d\u044b; \u0437\u0430\u0442\u0443\u0445\u0430\u044e\u0449\u0438\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430\u044f robustness-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430).\n- **\u0428\u0443\u043c** \u03b5_i(t) ~ N(0, \u03c3_e), \u03c3_e = 0.01 \u0440\u0430\u0434 \u2014 \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0438 \u0432 full, \u0438 \u0432 subsampled (subsampled = \u043f\u0440\u043e\u0441\u0442\u043e \u0432\u044b\u0431\u043e\u0440\u043a\u0430 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439).\n- **\u0427\u0430\u0441\u0442\u043e\u0442\u044b \u2014 \u0446\u0435\u043b\u044b\u0435 \u0434\u0435\u043b\u0438\u0442\u0435\u043b\u0438 T (\u043d\u0435\u0442 spectral leakage):** f = k/4096.\n  - Arm A: f_A = round(\u03b1 \u00b7 T/(2N))/T, \u03b1 \u2208 {0.5, 0.75, 0.9}, \u0441 assert f_A < 1/(2N). (N=4: k = 256, 384, 461.)\n  - Arm B: f_B = round(\u03b2 \u00b7 T/(2N))/T, \u03b2 \u2208 {1.25, 1.5, 1.75}. (N=4: k = 640, 768, 896.) \u0410\u043b\u0438\u0430\u0441-\u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u044f: f_alias = {0.75, 0.5, 0.25}\u00b7f_Nyq(N) \u2014 \u0432\u0441\u0435 \u0441\u0442\u0440\u043e\u0433\u043e \u043d\u0438\u0436\u0435 f_Nyq, \u0442.\u0435. **\u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u0432 input** \u0438 \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u043c\u044b (\u044d\u0442\u043e \u0438 \u0435\u0441\u0442\u044c \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u0438\u0433\u043d\u0430\u043b Arm B).\n  - \u041a\u0430\u0436\u0434\u044b\u0439 \u0443\u0433\u043e\u043b i \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442 \u0441\u0432\u043e\u044e \u0447\u0430\u0441\u0442\u043e\u0442\u0443 \u0438\u0437 \u0442\u0440\u0438\u043f\u043b\u0435\u043a\u0442\u0430 (4 \u0443\u0433\u043b\u0430: 3 \u0447\u0430\u0441\u0442\u043e\u0442\u044b + \u043e\u0434\u043d\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u0434\u043b\u044f \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438).\n- **Subsampled input:** x_k = \u03c6_i(k\u00b7N), k = 0..T/N\u22121. **N \u2208 {2, 4, 8}** \u0432 \u043e\u0431\u043e\u0438\u0445 arms.\n- **Train/test split:** \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0439 \u2014 train \u043d\u0430 \u043f\u0435\u0440\u0432\u044b\u0445 75% T, evaluation \u043d\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0445 25% (temporal generalization).\n\n## 3. Stand-in \u043c\u043e\u0434\u0435\u043b\u044c (plan A)\n\n**\u0410\u0432\u0442\u043e\u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u043e\u043d\u043d\u044b\u0439 \u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0439 \u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0442\u043e\u0440** (\u0447\u043b\u0435\u043d \u043a\u043b\u0430\u0441\u0441\u0430, \u0431\u0435\u0437 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a ground truth \u043f\u0440\u0438 \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441\u0435). \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e (arm, N, \u0443\u0433\u043e\u043b i) \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c. \u041f\u0440\u0438 \u043a\u0430\u0436\u0434\u043e\u043c subsampled k \u043c\u043e\u0434\u0435\u043b\u044c \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u0442 N\u22121 \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0445 \u0448\u0430\u0433\u0430:\n\n\u0177_{k,j} = w0 + w1\u00b7\u0177_{k,j\u22121} + w2\u00b7x_k + w3\u00b7x_{k\u22121} + w4\u00b7(j/N), j = 1..N\u22121, seed \u0177_{k,0} = x_k.\n\n\u041e\u0431\u0443\u0447\u0435\u043d\u0438\u0435: ridge-\u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f (\u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0435 \u0443\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f 5\u00d75, \u0440\u0435\u0448\u0430\u044e\u0442\u0441\u044f \u0413\u0430\u0443\u0441\u0441\u043e\u043c \u0432 stdlib) \u043f\u043e \u0432\u0441\u0435\u043c \u043f\u0430\u0440\u0430\u043c (k, j) \u0438\u0437 train-\u0441\u043f\u043b\u0438\u0442\u0430, target = \u03c6_i(k\u00b7N + j). \u041b\u0438\u043d\u0435\u0439\u043d\u0430\u044f AR-\u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0441 \u043f\u043e\u043b\u044e\u0441\u043e\u043c \u0441\u043f\u043e\u0441\u043e\u0431\u0435\u043d \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0438\u043d\u0443\u0441\u043e\u0438\u0434\u0443 \u043d\u0430 \u0432\u0445\u043e\u0434\u043d\u043e\u0439 \u0447\u0430\u0441\u0442\u043e\u0442\u0435 \u2014 \u044d\u0442\u043e \u0447\u0435\u0441\u0442\u043d\u044b\u0439 (\u0445\u043e\u0442\u044f \u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u044b\u0439 \u043f\u043e \u0451\u043c\u043a\u043e\u0441\u0442\u0438) \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u043a\u043b\u0430\u0441\u0441\u0430. **\u041f\u043b\u0430\u043d B** (\u0435\u0441\u043b\u0438 \u0440\u0435\u0448\u0438\u043c, \u0447\u0442\u043e \u043b\u0438\u043d\u0435\u0439\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e representative): \u0442\u0430 \u0436\u0435 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0441 MLP (\u0441\u043a\u0440\u044b\u0442\u044b\u0439 \u0441\u043b\u043e\u0439 16, manual backprop \u043d\u0430 stdlib) \u2014 \u0442\u043e\u0442 \u0436\u0435 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b, \u0431\u043e\u043b\u044c\u0448\u0435 \u0432\u0440\u0435\u043c\u044f; **\u043f\u043b\u0430\u043d B2** (fallback \u043f\u0440\u0438 \u043b\u044e\u0431\u043e\u043c runtime-\u0440\u0438\u0441\u043a\u0435): \u043d\u0435-\u043e\u0431\u0443\u0447\u0430\u0435\u043c\u044b\u0439 parametric fit \u2014 \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 band 2-\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u041c\u041d\u041a-\u043f\u043e\u0434\u0433\u043e\u043d\u043a\u0430 a\u00b7cos(2\u03c0ft)+b\u00b7sin(2\u03c0ft) \u043a residual + \u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u044b\u0435 baselines; \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438 controls, \u043d\u043e \u043d\u0435 \u00ab\u043c\u043e\u0434\u0435\u043b\u044c\u00bb.\n\n## 4. \u041c\u0435\u0442\u0440\u0438\u043a\u0438 (\u0442\u043e\u0447\u043d\u044b\u0435 \u0444\u043e\u0440\u043c\u0443\u043b\u044b)\n\n\u0414\u043b\u044f \u0440\u044f\u0434\u0430 y(t), t=0..T\u22121, \u043d\u0430 \u0447\u0430\u0441\u0442\u043e\u0442\u0435 f \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442\u044b:\n\u0100_f(y) = (2/T)\u00b7\u03a3_t y(t)\u00b7cos(2\u03c0ft); B\u0304_f(y) = (2/T)\u00b7\u03a3_t y(t)\u00b7sin(2\u03c0ft)\n\u00e2_f(y) = \u221a(\u0100_f\u00b2 + B\u0304_f\u00b2); \u03b8\u0302_f(y) = atan2(\u2212B\u0304_f, \u0100_f) (\u043a\u043e\u043d\u0432\u0435\u043d\u0446\u0438\u044f y \u2248 A\u00b7cos(2\u03c0ft+\u03b8)).\n\n\u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e (seed, N, arm, \u043c\u0435\u0442\u043e\u0434, \u0447\u0430\u0441\u0442\u043e\u0442\u0430, \u0443\u0433\u043e\u043b):\n1. **R_A(f) = \u00e2_f(\u0177)/\u00e2_f(y_gt)** \u2014 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u0430\u043c\u043f\u043b\u0438\u0442\u0443\u0434 (recovery ratio).\n2. **\u0394\u03b8(f) = min_{m\u2208Z} |\u03b8\u0302_f(\u0177) \u2212 \u03b8_f(gt) \u2212 m\u00b72\u03c0|** \u2014 \u043e\u0448\u0438\u0431\u043a\u0430 \u0444\u0430\u0437\u044b (\u0440\u0430\u0434\u0438\u0430\u043d\u044b).\n3. **SNR_f = \u00e2_f(\u0177) / \u00e2_f(y_gt \u2212 \u0177)** \u2014 \u0441\u043f\u0435\u043a\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u0439 SNR \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f.\n4. **Band energy ratio** E_fast(\u0177)/E_fast(y_gt), E_fast = \u00bd\u00b7\u03a3_{f\u2208F} \u00e2_f\u00b2; \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u043e E_slow (sanity: \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u0430 \u0436\u0435\u0440\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e\u0439 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u043e\u0439).\n5. **RMSE_fast** \u2014 RMSE(\u0177 \u2212 y_gt) \u043f\u043e\u0441\u043b\u0435 \u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u044f \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e\u0439 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b (\u043f\u0440\u043e\u0435\u043a\u0446\u0438\u044f \u043d\u0430 slow-\u0431\u0430\u043d\u0434 \u0438 \u043e\u0431\u0440\u0430\u0442\u043d\u043e).\n6. **Lag** \u2014 \u0441\u0434\u0432\u0438\u0433 \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430 \u043a\u0440\u043e\u0441\u0441-\u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0438 fast-\u0431\u0430\u043d\u0434\u043e\u0432 \u0177 \u0438 y_gt (\u0448\u0430\u0433\u0438; \u043e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f 0).\n7. **\u0414\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u044f \u043d\u0430 f_alias** (\u0442\u043e\u043b\u044c\u043a\u043e Arm B): \u00e2_{f_alias}(\u0177) \u2014 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442 \u043b\u0438 \u043c\u043e\u0434\u0435\u043b\u044c \u0430\u043b\u0438\u0430\u0441-\u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u0432\u043c\u0435\u0441\u0442\u043e \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439 \u0447\u0430\u0441\u0442\u043e\u0442\u044b.\n\n**\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430:** \u043f\u043e 20 seeds \u2014 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u00b1 95% CI; \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 model vs baseline \u2014 paired-\u0442\u0435\u0441\u0442 \u043f\u043e seeds (t-\u0442\u0435\u0441\u0442 \u0438\u043b\u0438 \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0439, stdlib). **\u041f\u043e\u043b-\u0448\u0443\u043c\u0430 (noise floor):** \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u044f y_gt \u043d\u0430 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0443\u044e \u0447\u0430\u0441\u0442\u043e\u0442\u0443 (\u043d\u0430\u043f\u0440., 1.5\u00b7f) \u0437\u0430\u0434\u0430\u0451\u0442 \u0431\u0430\u0437\u043e\u0432\u044b\u0439 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u00e2, \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0441\u0443\u0434\u0438\u043c \u00ab\u22480\u00bb.\n\n## 5. Baselines \u0438 controls (\u0441 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u043c \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435\u043c \u043a\u0430\u0436\u0434\u043e\u0433\u043e)\n\n| # | Control | Arm A (f < f_Nyq) | Arm B (f > f_Nyq) |\n|---|---|---|---|\n| C1 | **Sinc-\u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0446\u0438\u044f** \u03a3_k x_k\u00b7sinc((t\u2212kN)/N) \u2014 \u043e\u043f\u0442\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 band-limited \u0440\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0442\u043e\u0440 | R_A \u2248 1, \u0394\u03b8 \u043c\u0430\u043b\u043e \u2014 **\u0432\u0435\u0440\u0445\u043d\u044f\u044f \u0433\u0440\u0430\u043d\u044c** | R_A(\u0438\u0441\u0442\u0438\u043d\u043d\u0430\u044f f) \u2248 0; \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0430\u043b\u0438\u0430\u0441-\u0431\u0430\u043d\u0434 |\n| C2 | **\u041b\u0438\u043d\u0435\u0439\u043d\u0430\u044f \u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0446\u0438\u044f** | R_A < 1, \u0434\u0435\u0433\u0440\u0430\u0434\u0438\u0440\u0443\u0435\u0442 \u0441 \u0440\u043e\u0441\u0442\u043e\u043c N (sinc-\u043e\u0442\u043a\u0430\u0442 \u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0433\u043e \u044f\u0434\u0440\u0430) | \u2248 0 \u043d\u0430 \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439 f |\n| C3 | **Constant hold** (nearest) | R_A \u2248 0 (\u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e slow) | \u2248 0 |\n| C4 | **Null-\u043c\u043e\u0434\u0435\u043b\u044c** (\u043e\u0431\u0443\u0447\u0435\u043d\u0430 \u043d\u0430 target \u0431\u0435\u0437 fast-\u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b) | R_A \u2248 0 \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442, \u0447\u0442\u043e \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043d\u0435 \u0434\u0430\u044e\u0442 false positive \u043e\u0442 slow-\u0443\u0442\u0435\u0447\u043a\u0438 | \u2248 0 |\n| C5 | **Aliasing-\u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0430** (\u043f\u0440\u043e\u0435\u043a\u0446\u0438\u0438 \u043d\u0430 f_alias + \u0430\u0443\u0434\u0438\u0442 input): \u00e2_f(x_subsampled) \u043d\u0430 \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439 f_B \u2248 0 (input \u043d\u0435 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0438\u0441\u0442\u0438\u043d\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u043e\u0442\u0443); \u00e2_{f_alias}(\u0177) \u0432\u0435\u043b\u0438\u043a | \u2014 | \u0415\u0441\u043b\u0438 R_A(\u0438\u0441\u0442\u0438\u043d\u043d\u0430\u044f f) \u0432\u0434\u0440\u0443\u0433 \u0432\u044b\u0441\u043e\u043a\u0430 \u2192 \u0438\u0441\u043a\u0430\u0442\u044c \u0443\u0442\u0435\u0447\u043a\u0443/\u0437\u0430\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u0435, \u0430 \u043d\u0435 \u00ab\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435\u00bb |\n| C6 | **N-sweep** N \u2208 {2,4,8} | \u041a\u0440\u0438\u0432\u0430\u044f recovery vs N (\u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f \u043f\u0440\u0438 \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0435\u043d\u0438\u0438 f \u043a f_Nyq) | \u041f\u043b\u043e\u0441\u043a\u043e\u0435 \u2248 0 \u043d\u0430 \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439 f |\n| C7 | **Leave-one-frequency-out** (train \u043d\u0430 2 \u0438\u0437 3 \u0447\u0430\u0441\u0442\u043e\u0442, test \u043d\u0430 3-\u0439) | Performance \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u2192 \u043e\u0431\u043e\u0431\u0449\u0435\u043d\u0438\u0435, \u043d\u0435 \u0437\u0430\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u0435 | \u2248 0 |\n| C8 | **Metric null** (\u043f\u0440\u043e\u0435\u043a\u0446\u0438\u044f GT \u043d\u0430 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0443\u044e \u0447\u0430\u0441\u0442\u043e\u0442\u0443) | \u0437\u0430\u0434\u0430\u0451\u0442 noise floor \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u00ab\u22480\u00bb | \u0442\u043e \u0436\u0435 |\n| C9 (\u043e\u043f\u0446.) | **Cross-arm** (train \u043d\u0430 A, test \u043d\u0430 B) | \u2014 | \u041e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0432\u0430\u043b \u2014 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u0440\u0435\u0436\u0438\u043c\u0430 |\n\n## 6. Analysis plan \u0438 pass/fail \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438\n\n1. \u0413\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432 (seeds \u00d7 N \u00d7 arms \u2192 JSON/CSV \u0432 workspace).\n2. \u041e\u0431\u0443\u0447\u0435\u043d\u0438\u0435 stand-in per (arm, N, \u0443\u0433\u043e\u043b) \u043d\u0430 train-\u0441\u043f\u043b\u0438\u0442\u0435; \u043f\u0440\u043e\u0433\u043e\u043d \u0432\u0441\u0435\u0445 baselines (\u0431\u0435\u0437 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f).\n3. \u0420\u0430\u0441\u0447\u0451\u0442 \u043c\u0435\u0442\u0440\u0438\u043a \u00a74 per (seed, N, arm, \u043c\u0435\u0442\u043e\u0434, \u0447\u0430\u0441\u0442\u043e\u0442\u0430, \u0443\u0433\u043e\u043b) \u2192 \u0430\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u044f.\n4. **\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 Arm A (\u00ab\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 band-limited fast dynamics\u00bb):** R_A(model) \u2265 0.8 \u00b7 R_A(sinc) \u0418 R_A(model) \u2265 1.2 \u00b7 R_A(\u043b\u0438\u043d\u0435\u0439\u043d\u0430\u044f) \u0418 \u0394\u03b8 \u2264 0.25 \u0440\u0430\u0434 \u0418 R_A(null) < 0.2 \u00b7 R_A(sinc).\n5. **\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 Arm B (\u00ab\u043d\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u0443\u044e\u00bb):** R_A(\u0438\u0441\u0442\u0438\u043d\u043d\u0430\u044f f) \u2264 noise floor + 2\u03c3 (\u0442.\u0435. \u2272 0.15) \u0434\u043b\u044f \u0412\u0421\u0415\u0425 \u043c\u0435\u0442\u043e\u0434\u043e\u0432, \u0432\u043a\u043b\u044e\u0447\u0430\u044f model; C5 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442, \u0447\u0442\u043e \u044d\u043d\u0435\u0440\u0433\u0438\u044f \u043c\u043e\u0434\u0435\u043b\u0438 \u0432 Arm B \u0441\u0438\u0434\u0438\u0442 \u043d\u0430 f_alias, \u0430 \u043d\u0435 \u043d\u0430 \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439 f.\n6. **\u0418\u0442\u043e\u0433\u043e\u0432\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 (\u0448\u0430\u0431\u043b\u043e\u043d):** \u00ab\u041c\u043e\u0434\u0435\u043b\u0438 \u043a\u043b\u0430\u0441\u0441\u0430 MDGEN \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u044b \u0442\u043e\u0447\u043d\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0442\u044c band-limited \u0447\u0430\u0441\u0442\u044c \u0431\u044b\u0441\u0442\u0440\u044b\u0445 dynamics (\u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 Arm A: \u0446\u0438\u0444\u0440\u044b), \u043d\u043e \u043d\u0435 \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u044b \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0442\u044c aliased/\u0431\u0435\u0437\u0432\u043e\u0437\u0432\u0440\u0430\u0442\u043d\u043e \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c (Arm B: \u0446\u0438\u0444\u0440\u044b); \u0434\u043b\u044f \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0439 \u043e\u043d\u0438 \u043c\u043e\u0433\u0443\u0442 \u043b\u0438\u0448\u044c \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u0440\u0430\u0432\u0434\u043e\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0435 \u043e\u0441\u0446\u0438\u043b\u043b\u044f\u0446\u0438\u0438, \u0447\u0442\u043e \u043c\u0435\u0442\u0440\u0438\u043a\u0438 recovery \u043d\u0435 \u043c\u043e\u0433\u0443\u0442 \u043e\u0442\u043b\u0438\u0447\u0438\u0442\u044c \u043e\u0442 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0431\u0435\u0437 ground truth\u00bb.\n7. \u041e\u0442\u0447\u0451\u0442: markdown \u0441 \u0442\u0430\u0431\u043b\u0438\u0446\u0430\u043c\u0438 (\u043c\u0435\u0442\u043e\u0434 \u00d7 N \u00d7 arm \u00d7 \u043c\u0435\u0442\u0440\u0438\u043a\u0430), expected-vs-observed \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 control, caveat \u00a70, limitations.\n\n## 7. Feasibility\n\n- **stdlib-only** (math, random, json, csv, statistics) \u2014 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e: numpy/scipy \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442, \u0441\u0435\u0442\u044c \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u0430.\n- **Runtime (\u043e\u0446\u0435\u043d\u043a\u0430, \u043d\u0435 \u0437\u0430\u043c\u0435\u0440):** \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f 20\u00d73\u00d72\u00d74\u00d74096 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439 \u2014 \u0441\u0435\u043a\u0443\u043d\u0434\u044b; 24 ridge-\u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u0438 (5 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u043e\u0432, ~10^5 \u043e\u0431\u0440\u0430\u0437\u0446\u043e\u0432, \u0441\u0438\u0441\u0442\u0435\u043c\u044b 5\u00d75) \u2014 \u0441\u0435\u043a\u0443\u043d\u0434\u044b; \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u0438 ~3.2\u00d710^8 \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0439 \u0432 \u0447\u0438\u0441\u0442\u043e\u043c Python \u2014 ~\u043c\u0438\u043d\u0443\u0442\u0430. **\u0418\u0442\u043e\u0433\u043e \u226a 30 \u043c\u0438\u043d CPU**, GPU \u043d\u0435 \u043d\u0443\u0436\u0435\u043d. \u0420\u0438\u0441\u043a runtime \u043d\u0438\u0437\u043a\u0438\u0439; \u043f\u043b\u0430\u043d B/B2 \u2014 \u0441\u0442\u0440\u0430\u0445\u043e\u0432\u043a\u0430.\n- \u0414\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c: \u0432\u0441\u0435 seeds \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u2192 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c.\n\n## 8. Limitations (\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0432 \u043e\u0442\u0447\u0451\u0442\u0435)\n\n1. **Stand-in \u2260 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 MDGEN** \u2014 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u043a\u043b\u0430\u0441\u0441\u0430 \u043c\u043e\u0434\u0435\u043b\u0435\u0439; \u0434\u043b\u044f \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0433\u043e MDGEN \u0434\u0438\u0437\u0430\u0439\u043d \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c 1:1 (\u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c \u0437\u0430\u0433\u043b\u0443\u0448\u043a\u0443 \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u0443\u044e \u043c\u043e\u0434\u0435\u043b\u044c, \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u0430\u044f \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u043c\u0435\u0442\u0440\u0438\u043a/controls \u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f).\n2. \u0421\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 torsion dynamics (\u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 \u0441\u0438\u043d\u0443\u0441\u043e\u0438\u0434\u044b + random walk) \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442 \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u0443\u044e \u043c\u043d\u043e\u0433\u043e\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u0434\u0438\u043d\u0430\u043c\u0438\u043a\u0443, \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u044d\u043d\u0435\u0440\u0433\u0438\u0438, \u043d\u0435\u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0441\u0442\u0438/\u0430\u043d\u0433\u0430\u0440\u043c\u043e\u043d\u0438\u0447\u043d\u043e\u0441\u0442\u044c; \u00abfast dynamics\u00bb \u043f\u0440\u043e\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0441\u0438\u043d\u0443\u0441\u043e\u0438\u0434\u0430\u043c\u0438.\n3. Unwrapped \u0443\u0433\u043b\u044b, \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 torsion angles, \u043e\u0434\u043d\u0430 \u00ab\u0441\u0438\u0441\u0442\u0435\u043c\u0430\u00bb \u2014 \u043d\u0435\u0442 \u043e\u0431\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u043f\u043e \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430\u043c.\n4. \u041b\u0438\u043d\u0435\u0439\u043d\u0430\u044f AR-\u0437\u0430\u0433\u043b\u0443\u0448\u043a\u0430 \u043c\u043e\u0436\u0435\u0442 **\u0437\u0430\u043d\u0438\u0436\u0430\u0442\u044c** \u0451\u043c\u043a\u043e\u0441\u0442\u044c \u043d\u0435\u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439: \u0432 Arm A \u044d\u0442\u043e \u0432\u0435\u0440\u0445\u043d\u044f\u044f \u0433\u0440\u0430\u043d\u0438\u0446\u0430 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u043c\u0430 (\u0441\u0438\u043b\u044c\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043b\u0443\u0447\u0448\u0435), \u0432 Arm B \u2014 **\u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u043f\u0440\u0435\u0434\u0435\u043b, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0451\u043c\u043a\u043e\u0441\u0442\u044c \u043d\u0435 \u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0435\u0432\u0430\u0435\u0442** (\u0432\u044b\u0432\u043e\u0434 Arm B robust \u043a \u0432\u044b\u0431\u043e\u0440\u0443 \u043c\u043e\u0434\u0435\u043b\u0438).\n5. Finite-T leakage \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u043e \u0432\u044b\u0431\u043e\u0440\u043e\u043c f = k/4096; \u0430\u043b\u0438\u0430\u0441-\u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u044f Arm B \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442 \u043f\u043e \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0435 \u0441 \u0447\u0430\u0441\u0442\u043e\u0442\u0430\u043c\u0438 Arm A ({0.5, 0.75}\u00b7f_Nyq) \u2014 \u043d\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442, \u0442.\u043a. arms \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0